CREATE TYPE "CommentVisibility" AS ENUM ('INTERNAL','CLIENT');CREATE TYPE "ClientDecisionType" AS ENUM ('FAVORITE','INTERVIEW_REQUESTED','APPROVED','REJECTED','SELECTED');
CREATE TABLE "process_comments"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"vacancy_id" BIGINT NOT NULL,"author_user_id" BIGINT NOT NULL,"visibility" "CommentVisibility" NOT NULL,"body" TEXT NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deleted_at" TIMESTAMPTZ(6),FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT,FOREIGN KEY("vacancy_id") REFERENCES "vacancies"("id") ON DELETE CASCADE,FOREIGN KEY("author_user_id") REFERENCES "users"("id") ON DELETE RESTRICT);CREATE INDEX "process_comments_vacancy_id_visibility_created_at_idx" ON "process_comments"("vacancy_id","visibility","created_at");
CREATE TABLE "client_decisions"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"application_id" BIGINT NOT NULL,"user_id" BIGINT NOT NULL,"type" "ClientDecisionType" NOT NULL,"reason" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT,FOREIGN KEY("application_id") REFERENCES "applications"("id") ON DELETE RESTRICT,FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE RESTRICT);CREATE INDEX "client_decisions_tenant_id_application_id_created_at_idx" ON "client_decisions"("tenant_id","application_id","created_at");
